window.AUTH=window.AUTH||{};window.AUTH["19-715"]={"d":"19-715","id":"2019/19-715","n":"Trump v. Mazars USA, LLP","briefs":[{"k":"petitioner","label":"Brief of petitioners Donald J. Trump, et al.","date":"2020-01-27","url":"https://www.supremecourt.gov/DocketPDF/19/19-715/130092/20200127191622299_19-715%20and%2019-760%20Brief%20for%20Petitioners.pdf","side":"pet","n":83},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2020-02-03","url":"https://www.supremecourt.gov/DocketPDF/19/19-715/130825/20200203173620062_19-715tsacUnitedStates.pdf","side":"us","n":30},{"k":"respondent","label":"Brief of respondents Committees of the U.S. House of Representatives","date":"2020-02-26","url":"https://www.supremecourt.gov/DocketPDF/19/19-715/134253/20200226162318816_Nos%2019%20715%20760%20%20Merits%20Brief%20Final.pdf","side":"res","n":59},{"k":"reply","label":"Reply of petitioners Donald J. Trump, et al.","date":"2020-03-27","url":"https://www.supremecourt.gov/DocketPDF/19/19-715/139285/20200327114310120_19-715%2019-760_Reply%20Brief.pdf","side":"pet","n":46}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/591US2PP_web.pdf#page=407","tr":true,"items":[{"t":"case","label":"Pages(s) Cases: Alden v. Maine","cite":"527 U.S. 706","y":1999,"id":"1998/98-436","sc":1,"sum":"A sharply divided court held in a 5-4 decision that Congress may not use its Article I powers to abrogate the states' sovereign immunity. Both the terms and history of the eleventh amendment suggest that States are immune from suits in their own courts.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Anderson v. Dunn","cite":"19 U.S. 204","y":1821,"id":"1789-1850/19us204","sc":1,"op":1,"sum":"Though the contempt power will not be found in the Constitution in plain terms, necessity compels it. The power is inherent in the structure and purpose of Congress. The absence of such power would lead to a total loss of power, exposing the Congress \"to every indignity.\".","sumSrc":"Oyez","by":{"0":"32, 33, 53","3":"4, 5, 26"}},{"t":"case","label":"Armstrong v. Bush","cite":"924 F.2d 282","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/924/282/","by":{"0":"48, 57","2":"70"}},{"t":"case","label":"Ashland Oil, Inc. v. FTC","cite":"548 F.2d 977","y":1976,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/548/977/","by":{"0":"62"}},{"t":"case","label":"Ashwander v. Tennessee Valley Auth.","cite":"297 U.S. 288","y":1936,"id":"1900-1940/297us288","sc":1,"sum":"The Court held that Congress did not abuse its power with the TVA. Justice Hughes argued that the Wilson Dam, the location where the TVA was in the business of generating electricity, had been built originally in the interest of national defense: it produced materials involved in munitions manufacture. The government could sell excess electricity to consumers without violating the Constitution.","sumSrc":"Oyez","by":{"0":"55"}},{"t":"case","label":"Bank Markazi v. Peterson","cite":"136 S. Ct. 1310","y":2016,"id":"2015/14-770","sc":1,"op":14,"ar":2,"sum":"The Court decided that a statute effectively directing a particular result in a single pending case does not violate the separation of powers.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Barenblatt v. United States","cite":"360 U.S. 109","y":1959,"id":"1958/35","sc":1,"op":3,"ar":1,"sum":"The divided Court found that the Committee's actions did not violate the First Amendment and, thus, upheld Barenblatt's conviction for contempt of Congress. Justice Harlan noted that the First Amendment does not protect a witness from all lines of questioning. As long as the Congressional inquiry is pursued to \"aid the legislative process\" and to protect important government interests, then it is legitimate.","sumSrc":"Oyez","by":{"0":"36, 41, 43","2":"passim","3":"15, 19"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Bowsher v. Synar","cite":"478 U.S. 714","y":1986,"id":"1985/85-1377","sc":1,"op":1,"sum":"The Court found that the duties which the Congress delegated to the Comptroller General did violate the doctrine of separation of powers and were unconstitutional. A two step process led Chief Justice Burger to arrive at this conclusion.","sumSrc":"Oyez","by":{"0":"47-48, 58","1":"19","3":"24"}},{"t":"case","label":"Campbell v. Davidson","cite":"233 F.3d 1229","y":2000,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/233/1229/","by":{"0":"49"}},{"t":"case","label":"Cheney v. U.S. Dist. Court for D.C.","cite":"542 U.S. 367","y":2004,"id":"2003/03-475","sc":1,"op":3,"ar":1,"sum":"The Court sent the case back to the D.C. Court of Appeals, arguing that the appellate court should have considered separation-of-powers claims and was wrong to conclude it lacked authority to order District Court discovery to stop.","sumSrc":"Oyez","by":{"0":"36, 53, 54","1":"15, 16, 24, 34","2":"63","3":"30"}},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"sum":"A case in which the Court declared that pieces of legislation passed by both houses of Congress must be either passed or vetoed as a whole, not in separate parts.","sumSrc":"Oyez","by":{"0":"47","3":"26"}},{"t":"case","label":"Clinton v. Jones","cite":"520 U.S. 681","y":1997,"id":"1996/95-1853","sc":1,"op":3,"sum":"The Court found that the President did not have immunity from civil litigation.","sumSrc":"Oyez","by":{"0":"53, 64, 65","1":"1, 14, 15, 16, 20","2":"passim","3":"6, 12, 34"}},{"t":"case","label":"Comm. on Judiciary, U.S. House of Representatives v. Miers","cite":"558 F. Supp. 2d 53","y":2008,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/558/53/","by":{"0":"32"}},{"t":"case","label":"Eastland v. U.S. Servicemen’s Fund","cite":"421 U.S. 491","y":1975,"id":"1974/73-1923","sc":1,"op":4,"ar":6,"sum":"The Court held that the Senate Subcommittee's actions were legitimate and did not violate the Fund's First Amendment rights.","sumSrc":"Oyez","by":{"0":"passim","1":"12, 22","2":"passim","3":"8, 21"}},{"t":"case","label":"Exxon Corp. v. FTC","cite":"589 F.2d 582","y":1978,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/589/582/","by":{"0":"56"}},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"ar":1,"sum":"Evaluating the Secretary's chosen procedure under Article I Section 2 of the Constitution, however, Justice O'Connor ruled that the decision to include overseas personnel of the Department of Defense was a reasonable interpretation of the Constitution's intent. \"The Secretary's judgment does not hamper the underlying constitutional goal of equal representation, but, assuming that employees temporarily stationed abroad have indeed retained their ties to their home states, actually promotes equality,\" wrote Justice O'Connor.","sumSrc":"Oyez","by":{"0":"50, 57, 59, 60","1":"15, 22","2":"69, 70","3":"32, 33"}},{"t":"case","label":"Free Enter. Fund v. PCAOB","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"32, 46, 47","1":"17, 19, 22","2":"55, 61"}},{"t":"case","label":"Gordon v. United States","cite":"117 U.S. 697","y":1864,"url":"https://supreme.justia.com/cases/federal/us/117/697/","sc":1,"by":{"0":"46"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"sum":"In addition to emphasizing Missouri's, or any other state's, Tenth Amendment right to define the qualifications of its highest state officials, the Court held that the regulations of the ADEA did not apply to \"policy-making\" appointees such as state court judges.","sumSrc":"Oyez","by":{"0":"61"}},{"t":"case","label":"Hearst v. Black","cite":"87 F.2d 68","y":1936,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/87/68/","by":{"0":"52"}},{"t":"case","label":"Hutcheson v. United States","cite":"369 U.S. 599","y":1962,"id":"1961/46","sc":1,"sum":"In a 4-2 decision Justice John M. Harlan wrote for the majority and concluded that the Committee's questions were not outside the scope of the Senate investigation, nor were the Committee's questions asked simply to expose the union president's criminal acts. The fact that state prosecutors could have used the answers to the questions in a pending state criminal trial did not violate Due Process.","sumSrc":"Oyez","by":{"0":"37, 40, 42","2":"44, 48, 49, 53","3":"19, 20"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"op":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"0":"48, 58","1":"10, 17, 20, 33","3":"24"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"57","3":"5"}},{"t":"case","label":"Judicial Watch, Inc. v. U.S. Secret Service","cite":"726 F.3d 208","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/726/208/","by":{"0":"48","1":"25"}},{"t":"case","label":"Kilbourn v. Thompson","cite":"103 U.S. 168","y":1880,"id":"scdb/1880-103","sc":1,"op":15,"ar":6,"sum":"1. K., for refusing to answer certain questions put to him as a witness by the House of Representatives of the Congress of the United States, concerning the business of a real-estate partnership of which he was a member, and to produce certain books and papers in relation thereto, was, by an order of the House, imprisoned for forty-five days in the common jail of the District of Columbia. He brought suit to recover …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"passim","1":"12","2":"44, 53","3":"6, 15, 17"}},{"t":"case","label":"Kissinger v. Reporters Comm. for Freedom of the Press","cite":"445 U.S. 136","y":1980,"id":"1979/78-1088","sc":1,"sum":"Henry Kissinger served as an Assistant to the President for National Security Affairs from 1969 to 1975 and as Secretary of State from 1973 to 1977. Throughout these periods, his secretaries monitored his telephone conversations and recorded their contents either by shorthand or on tape. The stenographic notes or tapes were used to prepare summaries and sometimes verbatim transcripts of the conversations (hereafter …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"56"}},{"t":"case","label":"La. Public Service Comm’n v. FCC","cite":"476 U.S. 355","y":1986,"id":"1985/84-871","sc":1,"sum":"Section 152(b) bars federal pre-emption of state regulation over depreciation of dual jurisdiction property for intrastate ratemaking purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Marbury v. Madison","cite":"5 U.S. 137","y":1803,"id":"1789-1850/5us137","sc":1,"op":2,"sum":"A case in which the Court established a precedent for judicial review in the United States, declaring that acts of Congress that conflict with the Constitution are null and void, as the Constitution is the supreme law of the land.","sumSrc":"Oyez","by":{"0":"31","3":"5"}},{"t":"case","label":"Marshall v. Gordon","cite":"243 U.S. 521","y":1917,"id":"scdb/1916-125","sc":1,"op":2,"ar":1,"sum":"(1) That the proceedings concerning which the alleged contempt was committed were not impeachment proceedings.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"McCulloch v. Maryland","cite":"17 U.S. 316","y":1819,"id":"1789-1850/17us316","sc":1,"op":3,"sum":"The Court decided that the Second Bank of the United States could not be taxed by the state of Maryland, declaring that the government of individual states cannot impose laws on the functioning of the federal government.","sumSrc":"Oyez","by":{"0":"33, 35"}},{"t":"case","label":"McGrain v. Daugherty","cite":"273 U.S. 135","y":1927,"id":"1900-1940/273us135","sc":1,"op":18,"ar":3,"sum":"The Court upheld Daugherty's contempt conviction, establishing a presumption that congressional investigations have a legislative purpose. This presumption was not overcome by showing that the committee also had another purpose, such as exposure of wrongdoing. This presumption would later restrict the Court's hand in clear cases of congressional overreaching while investigating communists after World War II.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"McPhaul v. United States","cite":"364 U.S. 372","y":1960,"id":"1960/33","sc":1,"sum":"The conviction is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"52","3":"28"}},{"t":"case","label":"McSurely v. McClellan","cite":"521 F.2d 1024","y":1975,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/521/1024/","by":{"0":"36"}},{"t":"case","label":"Metzenbaum v. FERC","cite":"675 F.2d 1282","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/675/1282/","by":{"0":"56"}},{"t":"case","label":"Michigan v. EPA","cite":"268 F.3d 1075","y":2001,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/268/1075/","by":{"0":"47"}},{"t":"case","label":"Mississippi v. Johnson","cite":"71 U.S. 475","y":1866,"id":"1850-1900/71us475","sc":1,"sum":"The Court held that it had \"no jurisdiction of a bill to enjoin the President in the performance of his official duties....\" The Court held that the duties of the President as required by the Reconstruction Acts were \"in no sense ministerial,\" and that a judicial attempt to interfere with the performance of such duties would be \"an absurd and excessive extravagance.\" The Court noted that if the President chose to ignore the injunction, the judiciary would be unable to enforce the order.","sumSrc":"Oyez","by":{"0":"50"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"0":"47","2":"43"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"ar":1,"sum":"The near-unanimous Court held that the means of selecting the independent counsel did not violate the Appointments Clause; the powers allocated to the special court did not violate Article III; and the Act was not offensive to the separation of powers doctrine since it did not impermissibly interfere with the functions of the Executive Branch.","sumSrc":"Oyez","by":{"0":"14, 44, 47, 59","1":"23","2":"1, 55"}},{"t":"case","label":"NAMUDNO v. Holder","cite":"557 U.S. 193","y":2009,"id":"2008/08-322","sc":1,"sum":"The Court held that the Voting Rights Act (VRA) permits all political subdivisions to seek bailout from the preclearance requirements of the VRA.","sumSrc":"Oyez","by":{"0":"61"}},{"t":"case","label":"NCTA v. United States","cite":"415 U.S. 336","y":1974,"url":"https://supreme.justia.com/cases/federal/us/415/336/","sc":1,"by":{"0":"58"}},{"t":"case","label":"NFIB v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"ar":1,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"0":"32, 33, 51","3":"3, 6"}},{"t":"case","label":"Nixon v. Adm’r of Gen. Servs.","cite":"433 U.S. 425","y":1977,"id":"1976/75-1605","sc":1,"sum":"The Court held that the act did not violate any of Nixon’s relevant constitutional rights. Justice Brennan first determined that the district court correctly limited the scope of its review to the constitutional consequences of the archival screenings because the Administrator had not yet promulgated any regulations.","sumSrc":"Oyez","by":{"0":"11","1":"21","2":"passim"}},{"t":"case","label":"Nixon v. Fitzgerald","cite":"475 U.S. 731","y":1982,"id":"1981/79-1738","sc":1,"sum":"The Court held that the President \"is entitled to absolute immunity from damages liability predicated on his official acts.\" This sweeping immunity, argued Justice Powell, was a function of the \"President's unique office, rooted in the constitutional tradition of separation of powers and supported by our history.\".","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"60, 64","3":"6"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"op":3,"sum":"A case in which the Court further defined the limitations on the presidential powers granted by the Recess Appointments Clause.","sumSrc":"Oyez","by":{"0":"27, 31","2":"43, 62, 64","3":"9"}},{"t":"case","label":"NLRB v. SW General, Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"sum":"The Court determined that the limitations on nominees to vacant positions serving in an acting capacity under the Federal Vacancies Reform Act apply equally to first assistants who take on the position and to those who are selected by the President from within the same agency or from another agency.","sumSrc":"Oyez","by":{"0":"31","3":"13, 23"}},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"0":"24, 31, 33"}},{"t":"case","label":"Quinn v. United States","cite":"349 U.S. 155","y":1955,"id":"scdb/1954-078","sc":1,"op":3,"sum":"In his trial for contempt of Congress under 2 U. S. C. § 192, the District Court should have entered a judgment of acquittal.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36, 37, 45","1":"11, 13, 26","2":"42, 45","3":"19"}},{"t":"case","label":"Schaefer v. Townsend","cite":"215 F.3d 1031","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/215/1031/","by":{"0":"49","3":"25"}},{"t":"case","label":"Senate Select Comm. v. Nixon","cite":"498 F.2d 725","y":1974,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/498/725/","op":20,"ar":14,"by":{"0":"30, 40, 53","1":"23, 24, 28, 30","2":"67","3":"28"}},{"t":"case","label":"Sinclair v. United States","cite":"279 U.S. 263","y":1929,"id":"scdb/1928-056","sc":1,"sum":"(1) Neither the investigation authorized by the Senate's resolutions nor the question put by the committee related merely to the defendant's private affairs. P. 294. (2) Under Art. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","2":"47, 48","3":"19, 20"}},{"t":"case","label":"Tenney v. Brandhove","cite":"341 U.S. 367","y":1951,"id":"scdb/1950-081","sc":1,"sum":"From the allegations of the complaint, it appears that petitioners were acting in a field where legislators traditionally have power to act; and 8 U. S. C. §§ 43 and 47 (3) do not create civil liability for such conduct.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27","2":"44"}},{"t":"case","label":"Tobin v. United States","cite":"306 F.2d 270","y":1962,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/306/270/","ar":1,"by":{"0":"45, 61","1":"22, 33","3":"23"}},{"t":"case","label":"U.S. Term Limits, Inc. v. Thornton","cite":"514 U.S. 779","y":1995,"id":"1994/93-1456","sc":1,"op":1,"sum":"The Constitution prohibits States from adopting Congressional qualifications in addition to those enumerated in the Constitution.","sumSrc":"Oyez","by":{"0":"48, 49","2":"57","3":"25"}},{"t":"case","label":"United States ex rel. Attorney General v. Delaware & Hudson Co.","cite":"213 U.S. 366","y":1909,"id":"scdb/1908-137","sc":1,"sum":"Although a limitation to its operation might be reasonable and thus assuage the radical results of a prohibitory statute, if it is not'.expressed in the-statute-, to engraft such a limitation would be.pure-judicial legislation: IÁ construing the commodities clause of the Hepburn Act the\"suggestion' of the Government to limit its application to commodities while in the'hánds of a carrier or its first vendee, and, as …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"57"}},{"t":"case","label":"United States v. Ballin","cite":"144 U.S. 1","y":1892,"id":"scdb/1891-140","sc":1,"sum":"The provision in Rule XV of the House of Representatives of the fifty-first Congress, that “on the demand of any member, or at the suggestion of the Speaker, the names of members sufficient to make a quorum in the hall of the house who do not vote shall be noted by the clerk and recorded in the journal, and reported to the Speaker with the names of the members voting, and be counted and,-announced in determining the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"56"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"57"}},{"t":"case","label":"United States v. Burr","cite":"25 F. Cas. 187","y":1807,"court":"C.C.D. Va.","url":"https://www.courtlistener.com/c/F.%20Cas./25/187/","by":{"0":"53"}},{"t":"case","label":"United States v. Kebodeaux","cite":"570 U.S. 387","y":2013,"id":"2012/12-418","sc":1,"sum":"The Court held that the Necessary and Proper Clause gave Congress the power to create federal crimes and regulate their punishment, as well as apply the Sex Offender Registration and Notification Act (SORNA) on a defendant.","sumSrc":"Oyez","by":{"0":"33, 34, 35","3":"6"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"op":7,"sum":"The Court held that the President does not have executive privilege in immunity from subpoenas or other civil court actions.","sumSrc":"Oyez","by":{"0":"53","1":"15","2":"passim","3":"33"}},{"t":"case","label":"United States v. Rumely","cite":"345 U.S. 41","y":1953,"id":"scdb/1952-055","sc":1,"op":3,"ar":5,"sum":"The Committee was without power to exact the information sought from respondent.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"passim","3":"32"}},{"t":"case","label":"xiv United States v. Welden","cite":"377 U.S. 95","y":1964,"id":"1963/235","sc":1,"sum":"Appellee's testimony before the congressional subcommittee did not immunize him from prosecution, the Act of February 25, 1903, as amended in 1906, confining immunity to persons who testify in judicial proceedings under oath and in response to a subpoena. 215 F. Supp. 656, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Watkins v. United States","cite":"354 U.S. 178","y":1957,"id":"1956/261","sc":1,"op":6,"ar":7,"sum":"In a 6-to-1 decision, the Court held that the activities of the House Committee were beyond the scope of congressional power. The Court held that both the authorizing resolution of the Committee and the specific statements made by the Committee to Watkins failed to limit the Committee's power.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"15, 17, 19, 32"}},{"t":"case","label":"Wilkinson v. United States","cite":"365 U.S. 399","y":1961,"id":"1960/37","sc":1,"sum":"The Supreme Court held that the subcommittee’s investigation was clearly authorized by Congress. The question of whether Wilkin was a member of the Communist Party was relevant to the inquiry so Wilkinson was obligated to answer. The reasons why Wilkinson was called before the committee were irrelevant to the decision.","sumSrc":"Oyez","by":{"0":"40","2":"51","3":"15"}},{"t":"case","label":"Yellin v. United States","cite":"374 U.S. 109","y":1963,"id":"1961/35","sc":1,"sum":"On the record in this case, it appears that the Committee violated its own Rule IV by failing to give consideration to the question whether interrogation in public would injure petitioner's reputation and by failing to act on his request that he be interrogated in executive session; and petitioner's conviction for refusal to testify in public cannot stand.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"56, 62"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Kerry","cite":"135 S. Ct. 2076","y":2015,"id":"2014/13-628","sc":1,"sum":"The Court held that a federal statute directing the Secretary of State to record the birthplace of a citizen born in Jerusalem as “Israel” if requested to do so impermissibly infringed on the President’s power to recognize foreign states.","sumSrc":"Oyez","by":{"0":"33","3":"12"}},{"t":"const","label":"Article I, Section 5, Clause 2","text":"Each House may determine the Rules of its Proceedings, punish its Members for disorderly Behaviour, and, with the Concurrence of two thirds, expel a Member.","by":{"0":"2, 25","2":"12, 40, 62, 70"}},{"t":"const","label":"Article I, Section 8","by":{"0":"2, 46"}},{"t":"const","label":"Article I, Section 8, Clause 18","clauses":[["necessary-proper","Necessary and Proper Clause"]],"text":"To make all Laws which shall be necessary and proper for carrying into Execution the foregoing Powers, and all other Powers vested by this Constitution in the Government of the United States, or in any Department or Officer thereof.","by":{"0":"58","2":"43"}},{"t":"const","label":"Article I, Section 9","clauses":[["habeas","Suspension Clause (Habeas Corpus)"],["attainder-ex-post-facto","Bills of Attainder and Ex Post Facto Laws"],["appropriations","Appropriations Clause"],["emoluments","Emoluments Clauses"]],"by":{"0":"51"}},{"t":"const","label":"Article I, Section 9, Clause 8","clauses":[["emoluments","Emoluments Clauses"]],"text":"No Title of Nobility shall be granted by the United States: And no Person holding any Office of Profit or Trust under them, shall, without the Consent of the Congress, accept of any present, Emolument, Office, or Title, of any kind whatever, from any King, Prince, or foreign State.","by":{"0":"2, 50","2":"29, 56"}},{"t":"const","label":"Article II, Section 1, Clause 1","clauses":[["executive-vesting","Executive Vesting Clause"]],"text":"The executive Power shall be vested in a President of the United States of America. He shall hold his Office during the Term of four Years, and, together with the Vice President, chosen for the same Term, be elected, as follows","by":{"0":"2"}},{"t":"const","label":"Article II, Section 1, Clause 7","text":"The President shall, at stated Times, receive for his Services, a Compensation, which shall neither be encreased nor diminished during the Period for which he shall have been elected, and he shall not receive within that Period any other Emolument from the United States, or any of them.","by":{"0":"2, 50","2":"29"}},{"t":"const","label":"Article II, Section 2","clauses":[["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"]],"text":"The President shall be Commander in Chief of the Army and Navy of the United States, and of the Militia of the several States, when called into the actual Service of the United States; he may require the Opinion, in writing, of the principal Officer in each of the executive Departments, upon any Subject relating to the Duties of their respective Offices, and he shall have Power to grant Reprieves and Pardons for Offences against the United States, except in Cases of Impeachment. He shall have Power, by and with the Advice and Consent of the Senate, to make Treaties, provided two thirds of the Senators present concur; and he shall nominate, and by and with the Advice and Consent of the Senate, shall appoint Ambassadors, other public Ministers and Consuls, Judges of the supreme Court, and all other Officers of the United States, whose Appointments are not herein otherwise provided for, and which shall be established by Law: but the Congress may by Law vest the Appointment of such inferior Officers, as they think proper, in the President alone, in the Courts of Law, or in the Heads of Departments. The President shall have Power to fill up all Vacancies that may happen during the Recess of the Senate, by granting Commissions which shall expire at the End of their next Session.","by":{"0":"2"}},{"t":"const","label":"Article II, Section 3","clauses":[["take-care","Take Care Clause"]],"text":"He shall from time to time give to the Congress Information of the State of the Union, and recommend to their Consideration such Measures as he shall judge necessary and expedient; he may, on extraordinary Occasions, convene both Houses, or either of them, and in Case of Disagreement between them, with Respect to the Time of Adjournment, he may adjourn them to such Time as he shall think proper; he shall receive Ambassadors and other public Ministers; he shall take Care that the Laws be faithfully executed, and shall Commission all the Officers of the United States.","by":{"0":"2"}},{"t":"usc","label":"2 U.S.C. § 192","url":"https://www.law.cornell.edu/uscode/text/2/192","stext":{"head":"§192. Refusal of witness to testify or produce papers","paras":[[0,"Every person who having been summoned as a witness by the authority of either House of Congress to give testimony or to produce papers upon any matter under inquiry before either House, or any joint committee established by a joint or concurrent resolution of the two Houses of Congress, or any committee of either House of Congress, willfully makes default, or who, having appeared, refuses to answer any question pertinent to the question under inquiry, shall be deemed guilty of a misdemeanor, punishable by a fine of not more than $1,000 nor less than $100 and imprisonment in a common jail for not less than one month nor more than twelve months."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/2/192?type=usc&year=mostrecent&link-type=html"},"head":"§192. Refusal of witness to testify or produce papers","tname":"The Congress","by":{"0":"2, 58","2":"43, 45, 68"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(1)"],"by":{"0":"59"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(b)(1)"],"by":{"0":"59"}},{"t":"usc","label":"5 U.S.C. § 7342","url":"https://www.law.cornell.edu/uscode/text/5/7342","subs":["(a)","(a)(1)(E)"],"stext":{"head":"§7342. Receipt and disposition of foreign gifts and decorations","paras":[[0,"(a) For the purpose of this section—"],[1,"(1) \"employee\" means—"],[2,"(A) an employee as defined by section 2105 of this title and an officer or employee of the United States Postal Service or of the Postal Regulatory Commission;"],[2,"(B) an expert or consultant who is under contract under section 3109 of this title with the United States or any agency, department, or establishment thereof, including, in the case of an organization performing services under such section, any individual involved in the performance of such services;"],[2,"(C) an individual employed by, or occupying an office or position in, the government of a territory or possession of the United States or the government of the District of Columbia;"],[2,"(D) a member of a uniformed service;"],[2,"(E) the President and the Vice President;"],[2,"(F) a Member of Congress as defined by section 2106 of this title (except the Vice President) and any Delegate to the Congress; and"],[2,"(G) the spouse of an individual described in subparagraphs (A) through (F) (unless such individual and his or her spouse are separated) or a dependent (within the meaning of section 152 of the Internal Revenue Code of 1986) of such an individual, other than a spouse or dependent who is an employee under subparagraphs (A) through (F);"],[1,"(2) \"foreign government\" means—"],[2,"(A) any unit of foreign governmental authority, including any foreign national, State, local, and municipal government;"],[2,"(B) any international or multinational organization whose membership is composed of any unit of foreign government described in subparagraph (A); and"],[2,"(C) any agent or representative of any such unit or such organization, while acting as such;"],[1,"(3) \"gift\" means a tangible or intangible present (other than a decoration) tendered by, or received from, a foreign government;"],[1,"(4) \"decoration\" means an order, device, medal, badge, insignia, emblem, or award tendered by, or received from, a foreign government;"],[1,"(5) \"minimal value\" means a retail value in the United States at the time of acceptance of $100 or less, except that—"],[2,"(A) on January 1, 1981, and at 3 year intervals thereafter, \"minimal value\" shall be redefined in regulations prescribed by the Administrator of General Services, in consultation with the Secretary of State, to reflect changes in the consumer price index for the immediately preceding 3-year period; and"],[2,"(B) regulations of an employing agency may define \"minimal value\" for its employees to be less than the value established under this paragraph; and"],[1,"(6) \"employing agency\" means—"],[2,"(A) the Committee on Standards of Official Conduct of the House of Representatives, for Members and employees of the House of Representatives, except that those responsibilities specified in subsections (c)(2)(A), (e)(1), and (g)(2)(B) shall be carried out by the Clerk of the House;"],[2,"(B) the Select Committee on Ethics of the Senate, for Senators and employees of the Senate, except that those responsibilities (other than responsibilities involving approval of the employing agency) specified in subsections (c)(2), (d), and (g)(2)(B) shall be carried out by the Secretary of the Senate;"],[2,"(C) the Administrative Office of the United States Courts, for judges and judicial branch employees; and"],[2,"(D) the department, agency, office, or other entity in which an employee is employed, for other legislative branch employees and for all executive branch employees."],[0,"(b) An employee may not—"],[1,"(1) request or otherwise encourage the tender of a gift or decoration; or"],[1,"(2) accept a gift or decoration, other than in accordance with the provisions of subsections (c) and (d)."],[0,"(c)(1) The Congress consents to—"],[1,"(A) the accepting and retaining by an employee of a gift of minimal value tendered and received as a souvenir or mark of courtesy; and"],[1,"(B) the accepting by an employee of a gift of more than minimal value when such gift is in the nature of an educational scholarship or medical treatment or when it appears that to refuse the gift would likely cause offense or embarrassment or otherwise adversely affect the foreign relations of the United States, except that—"],[2,"(i) a tangible gift of more than minimal value is deemed to have been accepted on behalf of the United States and, upon acceptance, shall become the property of the United States; and"],[2,"(ii) an employee may accept gifts of travel or expenses for travel taking place entirely outside the United States (such as transportation, food, and lodging) of more than minimal value if such acceptance is appropriate, consistent with the interests of the United States, and permitted by the employing agency and any regulations which may be prescribed by the employing agency."],[0,"(2) Within 60 days after accepting a tangible gift of more than minimal value (other than a gift described in paragraph (1)(B)(ii)), an employee shall—"],[1,"(A) deposit the gift for disposal with his or her employing agency; or"],[1,"(B) subject to the approval of the employing agency, deposit the gift with that agency for official use."],[0,"Within 30 days after terminating the official use of a gift under subparagraph (B), the employing agency shall forward the gift to the Administrator of General Services in accordance with subsection (e)(1) or provide for its disposal in accordance with subsection (e)(2)."],[0,"(3) When an employee deposits a gift of more than minimal value for disposal or for official use pursuant to paragraph (2), or within 30 days after accepting travel or travel expenses as provided in paragraph (1)(B)(ii) unless such travel or travel expenses are accepted in accordance with specific instructions of his or her employing agency, the employee shall file a statement with his or her employing agency or its delegate containing the information prescribed in subsection (f) for that gift."],[0,"(d) The Congress consents to the accepting, retaining, and wearing by an employee of a decoration tendered in recognition of active field service in time of combat operations or awarded for other outstanding or unusually meritorious performance, subject to the approval of the employing agency of such employee. Without this approval, the decoration is deemed to have been accepted on behalf of the United States, shall become the property of the United States, and shall be deposited by the employee, within sixty days of acceptance, with the employing agency for official use, for forwarding to the Administrator of General Services for disposal in accordance with subsection (e)(1), or for disposal in accordance with subsection (e)(2)."],[0,"(e)(1) Except as provided in paragraph (2), gifts and decorations that have been deposited with an employing agency for disposal shall be (A) returned to the donor, or (B) forwarded to the Administrator of General Services for transfer, donation, or other disposal in accordance with the provisions of subtitle I of title 40 and division C (except sections 3302, 3501(b), 3509, 3906, 4710, and 4711) of subtitle I of title 41. However, no gift or decoration that has been deposited for disposal may be sold without the approval of the Secretary of State, upon a determination that the sale will not adversely affect the foreign relations of the United States. Gifts and decorations may be sold by negotiated sale."],[0,"(2) Gifts and decorations received by a Senator or an employee of the Senate that are deposited with the Secretary of the Senate for disposal, or are deposited for an official use which has terminated, shall be disposed of by the Commission on Arts and Antiquities of the United States Senate. Any such gift or decoration may be returned by the Commission to the donor or may be transferred or donated by the Commission, subject to such terms and conditions as it may prescribe, (A) to an agency or instrumentality of (i) the United States, (ii) a State, territory, or possession of the United States, or a political subdivision of the foregoing, or (iii) the District of Columbia, or (B) to an organization described in section 501(c)(3) of the Internal Revenue Code of 1986 which is exempt from taxation under section 501(a) of such Code. Any such gift or decoration not disposed of as provided in the preceding sentence shall be forwarded to the Administrator of General Services for disposal in accordance with paragraph (1). If the Administrator does not dispose of such gift or decoration within one year, he shall, at the request of the Commission, return it to the Commission and the Commission may dispose of such gift or decoration in such manner as it considers proper, except that such gift or decoration may be sold only with the approval of the Secretary of State upon a determination that the sale will not adversely affect the foreign relations of the United States."],[0,"(f)(1) Not later than January 31 of each year, each employing agency or its delegate shall compile a listing of all statements filed during the preceding year by the employees of that agency pursuant to subsection (c)(3) and shall transmit such listing to the Secretary of State who shall publish a comprehensive listing of all such statements in the Federal Register."],[0,"(2) Such listings shall include for each tangible gift reported—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7342?type=usc&year=mostrecent&link-type=html"},"head":"§7342. Receipt and disposition of foreign gifts and decorations","tname":"Government Organization and Employees","by":{"0":"51","2":"54"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1, 2"}},{"t":"usc","label":"44 U.S.C. § 2203","url":"https://www.law.cornell.edu/uscode/text/44/2203","subs":["(c)","(d)"],"by":{"0":"48, 48, 48"}},{"t":"case","label":"Bellis v. United States","cite":"417 U.S. 85","y":1974,"id":"1973/73-190","sc":1,"sum":"Fifth Amendment privilege against self-incrimination held not available to member of dissolved law partnership who had been subpoenaed by a grand jury to produce the partnership's financial books and records, since the partnership, though small, had an institutional identity and petitioner held the records in a representative, not a personal, capacity. The privilege is \"limited to its historic function of protecting …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Ford v. United States","cite":"273 U.S. 593","y":1927,"id":"scdb/1926-171","sc":1,"op":7,"sum":"1. In an indictment charging conspiracy to commit offenses against laws of the United States, an allegation that it was also to violate a treaty (prescribing no offense) may be rejected assurplusage.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Gravel v. United States","cite":"408 U.S. 606","y":1972,"id":"1971/71-1017","sc":1,"sum":"The Court held that because the work of aides was critical to the performance of legislative tasks and duties, they were nothing less than legislators' \"alter egos\" and thus immune from subpoenas by the Speech and Debate Clause. Aides were exempted from grand jury questioning so long as Senators invoked the privilege on their behalf.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Ho Ah Kow v. Nunan","cite":"12 F. Cas. 252","y":1879,"court":"C.C.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Cas./12/252/","by":{"1":"23"}},{"t":"case","label":"Hutchinson v. Proxmire","cite":"443 U.S. 111","y":1979,"id":"1978/78-680","sc":1,"sum":"The Court affirmed the decision of the lower court and held that Proxmire's statements in his newsletters and press releases were not protected by the Speech and Debate Clause. However, in upholding this ruling, the Court also found that Proxmire's statements were not made with \"actual malice\" and thus, were not libelous.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Powell v. McCormack","cite":"395 U.S. 486","y":1969,"id":"1968/138","sc":1,"sum":"After analyzing the Framers' debates on this issue, Chief Justice Warren concluded that since Powell had been lawfully elected by his constituents and since he met the constitutional requirements for membership in the House, that the chamber was powerless to exclude him.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Public Citizen v. United States Department of Justice","cite":"491 U.S. 440","y":1989,"id":"1988/88-429","sc":1,"sum":"To aid the President in fulfilling his constitutional duty to appoint federal judges, the Department of Justice regularly seeks advice from the Standing Committee on Federal Judiciary of the American Bar Association (ABA) regarding potential nominees for judgeships. The ABA Committee's investigations, reports, and votes on potential nominees are kept confidential, although its rating of a particular candidate is …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Salazar v. Buono","cite":"559 U.S. 700","y":2010,"id":"2009/08-472","sc":1,"sum":"The Court held that an individual has standing to maintain a suit when he acquires a \"judicially cognizable\" interest in ensuring compliance with a previous judgment in his favor. The Court also held that a court may not order an injunction in a case when it fails to consider all the circumstances bearing on the need for preventive relief.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"op":2,"sum":"The Court held that the President did not have the right to seize control of most of the country's steel mills to negate the effects of a suspected strike during the Korean War.","sumSrc":"Oyez","by":{"1":"19","2":"1"}},{"t":"usc","label":"5 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/5/552","by":{"1":"25"}},{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"2":"69"}},{"t":"case","label":"Chicago & N. W. Ry. Co. v. United Transp. Union","cite":"402 U.S. 570","y":1971,"id":"1970/189","sc":1,"sum":"Petitioner railroad brought this suit (after formal procedures of the Railway Labor Act had been exhausted) to enjoin a threatened strike by respondent Union, charging that the Union had failed to perform its obligations under § 2 First of the Railway Labor Act \"to exert every reasonable effort to make and maintain agreements concerning rates of pay, rules, and working conditions.\" The Union answered that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"57"}},{"t":"case","label":"Dellums v. Powell","cite":"561 F.2d 242","y":1977,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/561/242/","by":{"2":"67"}},{"t":"case","label":"Forrester v. White","cite":"484 U.S. 219","y":1988,"id":"1987/86-761","sc":1,"sum":"A state-court judge does not have absolute immunity from a damages suit under § 1983 for his decisions to demote and dismiss a court employee.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"60"}},{"t":"case","label":"Franchise Tax Bd. of Cal. v. Hyatt","cite":"139 S. Ct. 1485","y":2019,"id":"2018/17-1299","sc":1,"ar":1,"sum":"Nevada v. Hall, 440 U. S. 410, is overruled; States retain their sovereign immunity from private suits brought in courts of other States.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"43","3":"5"}},{"t":"case","label":"Glossip v. Gross","cite":"135 S. Ct. 2726","y":2015,"id":"2014/14-7955","sc":1,"sum":"The Court held that the use of midazolam as the initial drug in a state’s execution protocol does not violate the Eighth Amendment’s prohibition against cruel and unusual punishment.","sumSrc":"Oyez","by":{"2":"50","3":"19"}},{"t":"case","label":"Gojack v. United States","cite":"384 U.S. 702","y":1966,"id":"1965/594","sc":1,"sum":"1. \"A specific; properly authorized subject of inquiry is an essential element of the offense under § 192,\" and must be properly pleaded and proved.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"67, 68, 71"}},{"t":"case","label":"Goldwater v. Carter","cite":"444 U.S. 996","y":1979,"id":"1979/79-856","sc":1,"sum":"Without oral argument, the divided justices found that the case was not justiciable. Rehnquist led a group of four others who believed that the issue involved a political question, namely, how the President and Congress would conduct the nation's foreign affairs. Justice Powell did not find the case ripe for judicial review.","sumSrc":"Oyez","by":{"2":"64"}},{"t":"case","label":"People ex rel. McDonald v. Keeler","cite":"99 N.Y. 463","y":1885,"url":"https://www.courtlistener.com/c/N.Y./99/463/","by":{"2":"52"}},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"72"}},{"t":"case","label":"United States v. Burr","cite":"25 F. Cas. 30","y":1807,"court":"C.C.D. Va.","url":"https://www.courtlistener.com/c/F.%20Cas./25/30/","op":2,"by":{"2":"62"}},{"t":"case","label":"United States v. Centennial Builders, Inc.","cite":"747 F.2d 678","y":1984,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/747/678/","by":{"2":"65"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"op":2,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"2":"69"}},{"t":"case","label":"United States v. Miller","cite":"425 U.S. 435","y":1976,"id":"1975/74-1179","sc":1,"sum":"The Court reversed the Fifth Circuit and held that Miller had no right to privacy in his bank records. Writing for the majority, Justice Lewis F. Powell asserted that the \"documents subpoenaed are not [Miller's] 'private papers',\" but instead, part of the bank's business records.","sumSrc":"Oyez","by":{"2":"64, 65"}},{"t":"case","label":"United States v. R. Enters., Inc.","cite":"498 U.S. 292","y":1991,"id":"1990/89-1436","sc":1,"sum":"Pursuant to an investigation into allegations of interstate transportation of obscene materials, a federal grand jury sitting in the Eastern District of Virginia issued subpoenas duces tecum to Model Magazine Distributors, Inc. (Model), and to respondents R. Enterprises, Inc., and MFR Court Street Books, Inc. (MFR), all of which were based in New York and wholly owned by the same person. The subpoenas sought a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"54"}},{"t":"const","label":"Article I, Section 1","clauses":[["legislative-vesting","Legislative Vesting Clause"]],"text":"All legislative Powers herein granted shall be vested in a Congress of the United States, which shall consist of a Senate and House of Representatives.","by":{"2":"3, 42, 43","3":"6"}},{"t":"const","label":"Article I, Section 6, Clause 1","clauses":[["speech-debate","Speech or Debate Clause"]],"text":"The Senators and Representatives shall receive a Compensation for their Services, to be ascertained by Law, and paid out of the Treasury of the United States. They shall in all Cases, except Treason, Felony and Breach of the Peace, be privileged from Arrest during their Attendance at the Session of their respective Houses, and in going to and returning from the same; and for any Speech or Debate in either House, they shall not be questioned in any other Place.","by":{"2":"60, 61"}},{"t":"const","label":"Article I, Section 9, Clause 7","clauses":[["appropriations","Appropriations Clause"]],"text":"No Money shall be drawn from the Treasury, but in Consequence of Appropriations made by Law; and a regular Statement and Account of the Receipts and Expenditures of all public Money shall be published from time to time.","by":{"2":"3"}},{"t":"const","label":"Article II, Section 1, Clause 5","clauses":[["natural-born","Natural-Born Citizen Clause"]],"text":"No Person except a natural born Citizen, or a Citizen of the United States, at the time of the Adoption of this Constitution, shall be eligible to the Office of President; neither shall any Person be eligible to that Office who shall not have attained to the Age of thirty five Years, and been fourteen Years a Resident within the United States.","by":{"2":"57"}},{"t":"const","label":"Amendment XXV, Section 4","text":"Whenever the Vice President and a majority of either the principal officers of the executive departments or of such other body as Congress may by law provide, transmit to the President pro tempore of the Senate and the Speaker of the House of Representatives their written declaration that the President is unable to discharge the powers and duties of his office, the Vice President shall immediately assume the powers and duties of the office as Acting President. Thereafter, when the President transmits to the President pro tempore of the Senate and the Speaker of the House of Representatives his written declaration that no inability exists, he shall resume the powers and duties of his office unless the Vice President and a majority of either the principal officers of the executive department or of such other body as Congress may by law provide, transmit within four days to the President pro tempore of the Senate and the Speaker of the House of Representatives their written declaration that the President is unable to discharge the powers and duties of his office. Thereupon Congress shall decide the issue, assembling within forty-eight hours for that purpose if not in session. If the Congress, within twenty-one days after receipt of the latter written declaration, or, if Congress is not in session, within twenty-one days after Congress is required to assemble, determines by two-thirds vote of both Houses that the President is unable to discharge the powers and duties of his office, the Vice President shall continue to discharge the same as Acting President; otherwise, the President shall resume the powers and duties of his office.","by":{"2":"56"}},{"t":"usc","label":"2 U.S.C. § 682","url":"https://www.law.cornell.edu/uscode/text/2/682","by":{"2":"55"}},{"t":"usc","label":"12 U.S.C. § 1829b","url":"https://www.law.cornell.edu/uscode/text/12/1829b","subs":["(a)"],"by":{"2":"65"}},{"t":"usc","label":"18 U.S.C. § 431","url":"https://www.law.cornell.edu/uscode/text/18/431","by":{"2":"56"}},{"t":"usc","label":"22 U.S.C. § 9511","url":"https://www.law.cornell.edu/uscode/text/22/9511","by":{"2":"55"}},{"t":"usc","label":"31 U.S.C. § 5311","url":"https://www.law.cornell.edu/uscode/text/31/5311","by":{"2":"14"}},{"t":"usc","label":"31 U.S.C. § 5318","url":"https://www.law.cornell.edu/uscode/text/31/5318","subs":["(g)(2)(A)(i)","(h)(1)"],"by":{"2":"65, 18"}},{"t":"rule","label":"Fed. R. Crim. P. 17","url":"https://www.law.cornell.edu/rules/frcrmp/rule_17","subs":["(c)"],"by":{"2":"41, 58, 69"}},{"t":"case","label":"Coleman v. Miller","cite":"307 U.S. 433","y":1939,"id":"1900-1940/307us433","sc":1,"sum":"The Court held that the Kansas legislators had standing to sue, but found that two of the plaintiffs’ claims raised political questions that could only be resolved by Congress.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Dep’t of Commerce v. New York","cite":"139 S. Ct. 2551","y":2019,"id":"2018/18-966","sc":1,"sum":"The Secretary did not violate the Enumeration Clause or the Census Act in deciding to reinstate a citizenship question on the 2020 census questionnaire, but the District Court was warranted in remanding the case back to the agency where the evidence tells a story that does not match the Secretary’s explanation for his decision.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"12, 15"}},{"t":"case","label":"Guerrero-Lasprilla v. Barr, --- S. Ct. ---","cite":"2020 WL 1325822","y":2020,"court":"Mar. 23","sum":"Describing the question of “whether a given set of facts meets a particular legal standard as presenting a legal inquiry”.","sumSrc":"brief:3","by":{"3":"19"}},{"t":"case","label":"Hewitt v. Helms","cite":"482 U.S. 755","y":1987,"id":"1986/85-1630","sc":1,"sum":"Respondent is not a \"prevailing party\" eligible for attorney's fees under § 1988. A plaintiff must receive at least some relief on the merits of his claim before he can be said to \"prevail.\" Respondent obtained neither a damages award, injunction, or declaratory judgment, nor a consent decree, settlement, or other relief without benefit of a formal judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"22"}},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"sum":"In 1970, petitioner, who was then the Attorney General, authorized a warrantless wiretap for the purpose of gathering intelligence regarding the activities of a radical group that had made tentative plans to take actions threatening the Nation's security. During the time the wiretap was installed, the Government intercepted three conversations between a member of the group and respondent. Thereafter, this Court in …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"6"}},{"t":"case","label":"Northern Ins. Co. of N.Y. v. Chatham County, Ga.","cite":"547 U.S. 189","y":2006,"id":"2005/04-1618","sc":1,"sum":"The Court ruled that Chatham County was not entitled to immunity from suit. The opinion by Justice Clarence Thomas held that since the county was not acting as an \"arm of the state,\" it could not claim 11th Amendment immunity. The Court also refused to recognize a less expansive form of \"residual\" immunity for counties under common law.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Shelton v. United States","cite":"327 F.2d 601","y":1963,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/327/601/","by":{"3":"32"}},{"t":"case","label":"Shelton v. United States","cite":"404 F.2d 1292","y":1968,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/404/1292/","by":{"3":"17"}},{"t":"case","label":"United States v. AT&T","cite":"567 F.2d 121","y":1977,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/567/121/","sum":"Describing bipartisan cooperation and compromise.","sumSrc":"brief:3","by":{"3":"7"}},{"t":"case","label":"Vt. Agency of Natural Resources v. U.S. ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"const","label":"Article I, Section 2","clauses":[["apportionment","Apportionment and the Three-Fifths Clause"]],"by":{"3":"21"}},{"t":"const","label":"Article III, Section 1","clauses":[["judicial-vesting","Judicial Vesting Clause"]],"text":"The judicial Power of the United States, shall be vested in one supreme Court, and in such inferior Courts as the Congress may from time to time ordain and establish. The Judges, both of the supreme and inferior Courts, shall hold their Offices during good Behaviour, and shall, at stated Times, receive for their Services, a Compensation, which shall not be diminished during their Continuance in Office.","by":{"3":"6"}}]};